import{_ as t,o as r,c as a,a0 as o}from"./chunks/framework.DQOulFGV.js";const g=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"docs/architecture/overview.md","filePath":"docs/architecture/overview.md"}'),i={name:"docs/architecture/overview.md"};function s(n,e,d,l,c,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><h2 id="our-system" tabindex="-1">Our System <a class="header-anchor" href="#our-system" aria-label="Permalink to &quot;Our System&quot;">​</a></h2><p>Auditerra is built on three core principles:</p><ol><li><strong>Offline First:</strong> Field operations work in zero connectivity zones.</li><li><strong>Human Verified:</strong> Replace satellite guesses with on-the-ground data.</li><li><strong>Audit Ready:</strong> Every action is traceable and verifiable.</li></ol><h2 id="visual-diagrams" tabindex="-1">Visual Diagrams <a class="header-anchor" href="#visual-diagrams" aria-label="Permalink to &quot;Visual Diagrams&quot;">​</a></h2><h3 id="system-architecture-diagram" tabindex="-1">System Architecture Diagram <a class="header-anchor" href="#system-architecture-diagram" aria-label="Permalink to &quot;System Architecture Diagram&quot;">​</a></h3><blockquote><p><em>Click below to view the end-to-end system architecture.</em></p></blockquote><p><a href="https://lucid.app/lucidspark/4f756537-28a5-4ec6-93b5-b11e2f710a06/edit?viewport_loc=-54%2C-300%2C5760%2C3258%2C0_0&amp;invitationId=inv_b287c0c7-94d1-48cf-9f38-08a14172df1b" target="_blank" rel="noreferrer"><strong>View the Lucidchart Architecture Diagram</strong></a></p><hr><h2 id="system-components" tabindex="-1">System Components <a class="header-anchor" href="#system-components" aria-label="Permalink to &quot;System Components&quot;">​</a></h2><p>The system is built on a layered architecture, separating external users, application logic, and data services.</p><h3 id="_1-farmers-and-ussd-interface" tabindex="-1">1. Farmers and USSD Interface <a class="header-anchor" href="#_1-farmers-and-ussd-interface" aria-label="Permalink to &quot;1. Farmers and USSD Interface&quot;">​</a></h3><p><strong>Purpose:</strong> Allow smallholder farmers to report soil and agricultural issues using basic feature phones.</p><p><strong>How it works:</strong> Farmers dial <code>*384*55#</code>, collect their registration details (name, ID, phone, county, sub-county, landmark), and report an issue. The system generates a unique 4-digit handshake code and sends an SMS confirmation.</p><p><strong>Technology:</strong> Africa&#39;s Talking USSD API</p><p><strong>Security:</strong> Numeric inputs only; 30-second session timeout; phone numbers normalized.</p><h3 id="_2-reporting-module" tabindex="-1">2. Reporting Module <a class="header-anchor" href="#_2-reporting-module" aria-label="Permalink to &quot;2. Reporting Module&quot;">​</a></h3><p><strong>Purpose:</strong> Convert farmer USSD inputs into structured service tickets.</p><p><strong>How it works:</strong> Receives the issue category (Soil, Water, Crop, Erosion) and severity (Mild, Moderate, High), creates an immutable <code>PENDING</code> ticket record with a UUID, and triggers the expert matching process.</p><h3 id="_3-matching-service" tabindex="-1">3. Matching Service <a class="header-anchor" href="#_3-matching-service" aria-label="Permalink to &quot;3. Matching Service&quot;">​</a></h3><p><strong>Purpose:</strong> Find the most suitable field expert for each farmer&#39;s issue.</p><p><strong>How it works:</strong> Uses a multi-factor scoring matrix:</p><ul><li><strong>Proximity (40%):</strong> PostGIS spatial queries within a 15 km radius.</li><li><strong>Technical Specialization (35%):</strong> Matches expert skills with the reported issue.</li><li><strong>Language Compatibility (15%):</strong> Matches the farmer&#39;s preferred language.</li></ul><p>The system uses dynamic radius expansion: <code>15 km + 5</code>. <strong>Notifications:</strong> Farmers receive the expert&#39;s name and handshake code; Experts receive ticket details.</p><h3 id="_4-syncing-module" tabindex="-1">4. Syncing Module <a class="header-anchor" href="#_4-syncing-module" aria-label="Permalink to &quot;4. Syncing Module&quot;">​</a></h3><p><strong>Purpose:</strong> Enable offline-first field operations for experts.</p><p><strong>How it works:</strong> The expert PWA stores operational data locally in <strong>IndexedDB</strong>. The <strong>Service Worker</strong> intercepts network requests, and the <strong>Background Sync API</strong> detects connectivity, automatically uploading data when the network returns.</p><p><strong>Data Cached:</strong> Tickets (up to 10 days), diagnostic forms, location coordinates, and photos.</p><p><strong>Security:</strong> Highly Restricted data is not cached; JWT tokens expire after 1 hour.</p><h3 id="_5-location-module" tabindex="-1">5. Location Module <a class="header-anchor" href="#_5-location-module" aria-label="Permalink to &quot;5. Location Module&quot;">​</a></h3><p><strong>Purpose:</strong> Capture and manage geospatial data for farm visits.</p><p><strong>How it works:</strong> The expert&#39;s device captures GPS coordinates via the W3C Geolocation API. The backend stores them in PostgreSQL with PostGIS, allowing farm boundaries to be represented as spatial polygons.</p><h3 id="_6-verification-module" tabindex="-1">6. Verification Module <a class="header-anchor" href="#_6-verification-module" aria-label="Permalink to &quot;6. Verification Module&quot;">​</a></h3><p><strong>Purpose:</strong> Verify that field visits actually occurred and track restoration progress.</p><p><strong>How it works:</strong> Using a 4-digit handshake code:</p><ol><li>Code generated via <code>crypto.randomInt()</code>, hashed with bcrypt, and sent to the farmer.</li><li>Expert enters the code on site. Successful verification unlocks diagnostic forms (code expires after 24 hours).</li><li>A 60-day mandatory retest loop is scheduled to measure restoration progress.</li></ol><h3 id="_7-ai-module" tabindex="-1">7. AI Module <a class="header-anchor" href="#_7-ai-module" aria-label="Permalink to &quot;7. AI Module&quot;">​</a></h3><p><strong>Purpose:</strong> Generate agronomic recommendations using Retrieval-Augmented Generation (RAG).</p><p><strong>How it works:</strong></p><ol><li><strong>Knowledge Base:</strong> Project-specific Markdown files are uploaded to the Gemini File Search store.</li><li><strong>Prompt Construction:</strong> The backend strips farmer identity, structures soil parameters, and restricts the response format.</li><li><strong>RAG Execution:</strong> Gemini retrieves relevant documents to ground the recommendation.</li><li><strong>Output Generation:</strong> Produces a Farmer SMS, Expert Brief, and Institutional Data displayed on the dashboard.</li></ol><p><strong>Security:</strong> Farmer identity is removed before AI requests; outputs are constrained; input/output hashes are maintained for audit purposes.</p><h3 id="_8-sms-alert-module" tabindex="-1">8. SMS Alert Module <a class="header-anchor" href="#_8-sms-alert-module" aria-label="Permalink to &quot;8. SMS Alert Module&quot;">​</a></h3><p><strong>Purpose:</strong> Deliver prescriptions, verification codes, and operational notifications. <strong>How it works:</strong></p><ul><li><strong>Primary Channel:</strong> Africa&#39;s Talking</li><li><strong>Secondary Channel:</strong> SMS Leopard (Failover)</li><li><strong>Retry Policy:</strong> Failed messages are retried up to 3 times. <strong>Security:</strong> API keys stored in Secret Manager; 10 SMS/day max for farmers, 100/day max for experts; passwords/GPS are never included.</li></ul><h3 id="_9-supervisor-dashboard" tabindex="-1">9. Supervisor Dashboard <a class="header-anchor" href="#_9-supervisor-dashboard" aria-label="Permalink to &quot;9. Supervisor Dashboard&quot;">​</a></h3><p><strong>Purpose:</strong> Provide institutional supervisors with operational oversight and audit capabilities. <strong>Features:</strong> Interactive national map, real-time ticket tracking, expert deployment density, 60-day audit reminders, and exportable impact reports.</p><hr><h2 id="data-flow-and-system-integration" tabindex="-1">Data Flow and System Integration <a class="header-anchor" href="#data-flow-and-system-integration" aria-label="Permalink to &quot;Data Flow and System Integration&quot;">​</a></h2><p>The architecture follows a strict, secure data path:</p><ol><li><strong>Report:</strong> Farmer dials <code>*384*55#</code> → USSD menu → Issue category &amp; severity submitted.</li><li><strong>Match:</strong> Backend uses PostGIS + Multi-factor scoring → Expert assigned → Status: <code>MATCHED</code>.</li><li><strong>Verify:</strong> Expert travels to farm → GPS captured → Handshake code entered → Status: <code>ON_SITE</code>.</li><li><strong>Diagnose:</strong> Expert records soil parameters and photos offline → Data synced when connectivity returns.</li><li><strong>Prescribe:</strong> Data syncs → AI generates recommendation (anonymized) → Delivered via SMS/PWA/Dashboard → 60-day retest scheduled.</li></ol><hr><h2 id="design-brand-guidelines" tabindex="-1">Design &amp; Brand Guidelines <a class="header-anchor" href="#design-brand-guidelines" aria-label="Permalink to &quot;Design &amp; Brand Guidelines&quot;">​</a></h2><p>The Auditerra interface is designed for readability and clarity, specifically optimized for mobile devices and low-bandwidth environments. The visual design choices follow a professional, agricultural aesthetic focusing on clarity and trust.</p><h3 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h3><ul><li><strong>Low Connectivity Focus:</strong> The interface is designed for mobile-first usage, ensuring fast loading times even on 2G networks.</li><li><strong>Simple and Clear:</strong> Icons are used heavily to bypass language barriers, and color coding is used to quickly indicate statuses (e.g., Green for success, Red for emergencies).</li><li><strong>Accessibility:</strong> High contrast ratios are used for text and backgrounds to ensure readability in outdoor field conditions.</li></ul><h3 id="color-palette" tabindex="-1">Color Palette <a class="header-anchor" href="#color-palette" aria-label="Permalink to &quot;Color Palette&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Color</th><th>Hex</th><th>Usage</th></tr></thead><tbody><tr><td>Primary</td><td>Brown</td><td><code>#5B3D26</code></td><td>Headings and navigation</td></tr><tr><td>Primary</td><td>White</td><td><code>#FFFFFF</code></td><td>Backgrounds and text on dark surfaces</td></tr><tr><td>Secondary</td><td>Green</td><td><code>#4C8A42</code></td><td>Buttons and success states</td></tr><tr><td>Secondary</td><td>Teal</td><td><code>#436A4B</code></td><td>Accent elements</td></tr></tbody></table><h3 id="typography" tabindex="-1">Typography <a class="header-anchor" href="#typography" aria-label="Permalink to &quot;Typography&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>Primary Font</td><td>Fira Sans</td></tr><tr><td>Weights</td><td>Regular, Medium, Bold</td></tr><tr><td>Hierarchy</td><td>Headings: Bold, Body: Regular</td></tr></tbody></table><h3 id="figma-design-references" tabindex="-1">Figma Design References <a class="header-anchor" href="#figma-design-references" aria-label="Permalink to &quot;Figma Design References&quot;">​</a></h3><blockquote><p><em>Click below to view the Figma designs, including the brand moodboard, style guide, wireframes, and the full Web UI.</em></p></blockquote><p><a href="https://www.figma.com/design/DvUaZIM2Po8pyEREPgUCSq/Sci-Sync-Case-study?node-id=1-3&amp;t=6fCnJa56zdMW6Svo-1" target="_blank" rel="noreferrer"><strong>View the Figma Design Files</strong></a></p>',62)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
